421: // 4-times unrolled loop
422: #define DUFFS_LOOP4(pixel_copy_increment, width)                        \
423: { int n = (width+3)/4;                                                  \
424:     switch (width & 3) {                                                \
425:     case 0: do {    pixel_copy_increment;   /* fallthrough */           \
426:     case 3:     pixel_copy_increment;       /* fallthrough */           \
427:     case 2:     pixel_copy_increment;       /* fallthrough */           \
428:     case 1:     pixel_copy_increment;       /* fallthrough */           \
429:         } while (--n > 0);                                              \
430:     }                                                                   \
431: }
432: 
433: #else
434: 
435: // Don't use Duff's device to unroll loops
436: #define DUFFS_LOOP(pixel_copy_increment, width)                         \
437: { int n;                                                                \
438:     for ( n=width; n > 0; --n ) {                                       \
439:         pixel_copy_increment;                                           \
440:     }                                                                   \
441: }
442: 
443: #define DUFFS_LOOP4(pixel_copy_increment, width)                        \
444:     DUFFS_LOOP(pixel_copy_increment, width)
445: 
446: #endif
