449: // Blend colored glyphs
450: static void BG_Blended_Color(const TTF_Image *image, Uint32 *destination, Sint32 srcskip, Uint32 dstskip, Uint8 fg_alpha)
451: {
452:     const Uint8  *src   = image->buffer;
453:     Uint32      *dst    = destination;
454:     Uint32       width  = image->width;
455:     Uint32       height = image->rows;
456: 
457:     if (fg_alpha == SDL_ALPHA_OPAQUE) {
458:         while (height--) {
459:             /* *INDENT-OFF* */
460:             DUFFS_LOOP4(
461:                 SDL_memcpy(dst, src, sizeof(Uint32));
462:                 src += sizeof(Uint32);
463:                 dst += 1;
464:             , width);
465:             /* *INDENT-ON* */
466:             src += srcskip;
467:             dst = (Uint32 *)((Uint8 *)dst + dstskip);
468:         }
469:     } else {
470:         Uint32 alpha;
471:         Uint32 tmp;
472: 
473:         while (height--) {
474:             /* *INDENT-OFF* */
475:             DUFFS_LOOP4(
476:                     /* prevent misaligned load: tmp = *src++; */
477:                     // eventually, we can expect the compiler to replace the memcpy call with something optimized
478:                     SDL_memcpy(&tmp, src, sizeof(tmp));
479:                     src += sizeof(Uint32);
480:                     alpha = tmp >> 24;
481:                     tmp &= ~0xFF000000;
482:                     alpha = fg_alpha * alpha;
483:                     alpha =  DIVIDE_BY_255(alpha) << 24;
484:                     *dst++ = tmp | alpha
485:                     , width);
486:             /* *INDENT-ON* */
487:             src += srcskip;
488:             dst = (Uint32 *)((Uint8 *)dst + dstskip);
489:         }
490:     }
491: }
