493: // Blend with LCD rendering
494: static void BG_Blended_LCD(const TTF_Image *image, Uint32 *destination, Sint32 srcskip, Uint32 dstskip, SDL_Color *fg)
495: {
496:     const Uint8 *src    = image->buffer;
497:     Uint32      *dst    = destination;
498:     Uint32       width  = image->width;
499:     Uint32       height = image->rows;
500: 
501:     Uint32 tmp, bg;
502:     Uint32 r, g, b;
503:     Uint8 fg_r, fg_g, fg_b;
504:     Uint8 bg_r, bg_g, bg_b;
505:     Uint32 bg_a;
506: 
507:     fg_r = fg->r;
508:     fg_g = fg->g;
509:     fg_b = fg->b;
510: 
511:     while (height--) {
512:         /* *INDENT-OFF* */
513:         DUFFS_LOOP4(
514:                 SDL_memcpy(&tmp, src, sizeof(tmp));
515:                 src += sizeof(Uint32);
516: 
517:                 if (tmp) {
518:                     bg = *dst;
519: 
520:                     bg_a = bg & 0xff000000;
521:                     bg_r = (bg >> 16) & 0xff;
522:                     bg_g = (bg >> 8) & 0xff;
523:                     bg_b = (bg >> 0) & 0xff;
524: 
525:                     r = (tmp >> 16) & 0xff;
526:                     g = (tmp >> 8) & 0xff;
527:                     b = (tmp >> 0) & 0xff;
528: 
529:                     r = fg_r * r + bg_r * (255 - r) + 127;
530:                     r = DIVIDE_BY_255(r);
531: 
532:                     g = fg_g * g + bg_g * (255 - g) + 127;
533:                     g = DIVIDE_BY_255(g);
534: 
535:                     b = fg_b * b + bg_b * (255 - b) + 127;
536:                     b = DIVIDE_BY_255(b);
537: 
538:                     r <<= 16;
539:                     g <<= 8;
540:                     b <<= 0;
541: 
542:                     *dst = r | g | b | bg_a;
543:                 }
544:                 dst++;
545: 
546:                 , width);
