647: // This does an unaligned SIMD load, the pointer cast is technically UB but no compiler
648: // probably actually cares as long as the alignment sanitizer is disabled, the wrapper is
649: // necessary to have the smallest surface where the sanitizer is turned off
650: static inline __m128i __attribute__((no_sanitize("alignment"))) _mm_loadu_si128_unaligned(const void *ptr) {
651:     return _mm_loadu_si128(ptr);
