654: // Apply: alpha_table[i] = i << 24;
655: static void BG_Blended_Opaque_SSE(const TTF_Image *image, Uint32 *destination, Sint32 srcskip, Uint32 dstskip)
656: {
657:     const Uint8   *src    = image->buffer;
658:     __m128i       *dst    = (__m128i *)destination;
659:     Uint32         width  = image->width / 16;
660:     Uint32         height = image->rows;
661: 
662:     __m128i s, s0, s1, s2, s3, d0, d1, d2, d3, r0, r1, r2, r3, L, H;
663:     const __m128i zero  = _mm_setzero_si128();
664: 
665:     while (height--) {
666:         /* *INDENT-OFF* */
667:         DUFFS_LOOP4(
668:             // Read 16 Uint8 at once and put into 4 __m128i
669:             s  = _mm_loadu_si128_unaligned(src);// load unaligned
670:             d0 = _mm_load_si128(dst);           // load
671:             d1 = _mm_load_si128(dst + 1);       // load
672:             d2 = _mm_load_si128(dst + 2);       // load
673:             d3 = _mm_load_si128(dst + 3);       // load
674: 
675:             L  = _mm_unpacklo_epi8(zero, s);
676:             H  = _mm_unpackhi_epi8(zero, s);
677: 
678:             s0 = _mm_unpacklo_epi8(zero, L);
679:             s1 = _mm_unpackhi_epi8(zero, L);
680:             s2 = _mm_unpacklo_epi8(zero, H);
681:             s3 = _mm_unpackhi_epi8(zero, H);
682:                                                 // already shifted by 24
683:             r0 = _mm_or_si128(d0, s0);          // or
684:             r1 = _mm_or_si128(d1, s1);          // or
685:             r2 = _mm_or_si128(d2, s2);          // or
686:             r3 = _mm_or_si128(d3, s3);          // or
687: 
688:             _mm_store_si128(dst, r0);           // store
689:             _mm_store_si128(dst + 1, r1);       // store
690:             _mm_store_si128(dst + 2, r2);       // store
691:             _mm_store_si128(dst + 3, r3);       // store
692: 
693:             dst += 4;
694:             src += sizeof(__m128i);
695:         , width);
696:         /* *INDENT-ON* */
697:         src += srcskip;
698:         dst = (__m128i *)((Uint8 *)dst + dstskip);
699:     }
700: }
