702: static void BG_Blended_SSE(const TTF_Image *image, Uint32 *destination, Sint32 srcskip, Uint32 dstskip, Uint8 fg_alpha)
703: {
704:     const Uint8   *src    = image->buffer;
705:     __m128i       *dst    = (__m128i *)destination;
706:     Uint32         width  = image->width / 16;
707:     Uint32         height = image->rows;
708: 
709:     const __m128i alpha = _mm_set1_epi16(fg_alpha);
710:     const __m128i one   = _mm_set1_epi16(1);
711:     const __m128i zero  = _mm_setzero_si128();
712:     __m128i s, s0, s1, s2, s3, d0, d1, d2, d3, r0, r1, r2, r3, L, H, Ls8, Hs8;
713: 
714:     while (height--) {
715:         /* *INDENT-OFF* */
716:         DUFFS_LOOP4(
717:             // Read 16 Uint8 at once and put into 4 __m128i
718:             s  = _mm_loadu_si128_unaligned(src);// load unaligned
719:             d0 = _mm_load_si128(dst);           // load
720:             d1 = _mm_load_si128(dst + 1);       // load
721:             d2 = _mm_load_si128(dst + 2);       // load
722:             d3 = _mm_load_si128(dst + 3);       // load
723: 
724:             L  = _mm_unpacklo_epi8(s, zero);    // interleave, no shifting
725:             H  = _mm_unpackhi_epi8(s, zero);    // enough room to multiply
726: 
727:             /* Apply: alpha_table[i] = ((i * fg.a / 255) << 24; */
728:             // Divide by 255 is done as:    (x + 1 + (x >> 8)) >> 8
729: 
730:             L  = _mm_mullo_epi16(L, alpha);     // x := i * fg.a
731:             H  = _mm_mullo_epi16(H, alpha);
732: 
733:             Ls8 = _mm_srli_epi16(L, 8);         // x >> 8
734:             Hs8 = _mm_srli_epi16(H, 8);
735:             L = _mm_add_epi16(L, one);          // x + 1
736:             H = _mm_add_epi16(H, one);
737:             L = _mm_add_epi16(L, Ls8);          // x + 1 + (x >> 8)
738:             H = _mm_add_epi16(H, Hs8);
739:             L = _mm_srli_epi16(L, 8);           // ((x + 1 + (x >> 8)) >> 8
740:             H = _mm_srli_epi16(H, 8);
741: 
742:             L = _mm_slli_epi16(L, 8);           // shift << 8, so we're prepared
743:             H = _mm_slli_epi16(H, 8);           // to have final format << 24
744: 
745:             s0 = _mm_unpacklo_epi8(zero, L);
746:             s1 = _mm_unpackhi_epi8(zero, L);
747:             s2 = _mm_unpacklo_epi8(zero, H);
748:             s3 = _mm_unpackhi_epi8(zero, H);
749:                                                 // already shifted by 24
750: 
751:             r0 = _mm_or_si128(d0, s0);          // or
752:             r1 = _mm_or_si128(d1, s1);          // or
753:             r2 = _mm_or_si128(d2, s2);          // or
754:             r3 = _mm_or_si128(d3, s3);          // or
755: 
756:             _mm_store_si128(dst, r0);           // store
757:             _mm_store_si128(dst + 1, r1);       // store
758:             _mm_store_si128(dst + 2, r2);       // store
759:             _mm_store_si128(dst + 3, r3);       // store
760: 
761:             dst += 4;
762:             src += sizeof(__m128i);
763:         , width);
764:         /* *INDENT-ON* */
765:         src += srcskip;
766:         dst = (__m128i *)((Uint8 *)dst + dstskip);
767:     }
768: }
769: #endif
