819: // Non-opaque, computes alpha blending on the fly
820: static void BG_Blended_NEON(const TTF_Image *image, Uint32 *destination, Sint32 srcskip, Uint32 dstskip, Uint8 fg_alpha)
821: {
822:     const Uint32 *src    = (Uint32 *)image->buffer;
823:     Uint32       *dst    = destination;
824:     Uint32        width  = image->width / 16;
825:     Uint32        height = image->rows;
826: 
827:     uint32x4_t s, d0, d1, d2, d3, r0, r1, r2, r3;
828:     uint16x8_t Ls8, Hs8;
829:     uint8x16x2_t sx, sx01, sx23;
830:     uint16x8x2_t sxm;
831: 
832:     const uint16x8_t alpha = vmovq_n_u16(fg_alpha);
833:     const uint16x8_t one   = vmovq_n_u16(1);
834:     const uint8x16_t zero  = vdupq_n_u8(0);
835: 
836:     while (height--) {
837:         /* *INDENT-OFF* */
838:         DUFFS_LOOP4(
839:             /* Read 4 Uint32 and put 16 Uint8 into uint32x4x2_t (uint8x16x2_t)
840:              * takes advantage of vzipq_u8 which produces two lanes */
841: 
842:             s  = vld1q_u32(src);                                    // load
843:             d0 = vld1q_u32(dst);                                    // load
844:             d1 = vld1q_u32(dst + 4);                                // load
845:             d2 = vld1q_u32(dst + 8);                                // load
846:             d3 = vld1q_u32(dst + 12);                               // load
847: 
848:             sx = vzipq_u8((uint8x16_t)s, zero);                     // interleave, no shifting
849:                                                                     // enough room to multiply
850: 
851:             /* Apply: alpha_table[i] = ((i * fg.a / 255) << 24; */
852:             // Divide by 255 is done as:    (x + 1 + (x >> 8)) >> 8
853: 
854:             sxm.val[0] = vmulq_u16((uint16x8_t)sx.val[0], alpha);   // x := i * fg.a
855:             sxm.val[1] = vmulq_u16((uint16x8_t)sx.val[1], alpha);
856: 
857:             Ls8 = vshrq_n_u16(sxm.val[0], 8);                       // x >> 8
858:             Hs8 = vshrq_n_u16(sxm.val[1], 8);
859: 
860:             sxm.val[0] = vaddq_u16(sxm.val[0], one);                // x + 1
861:             sxm.val[1] = vaddq_u16(sxm.val[1], one);
862: 
863:             sxm.val[0] = vaddq_u16(sxm.val[0], Ls8);                // x + 1 + (x >> 8)
864:             sxm.val[1] = vaddq_u16(sxm.val[1], Hs8);
865: 
866:             sxm.val[0] = vshrq_n_u16(sxm.val[0], 8);                // ((x + 1 + (x >> 8)) >> 8
867:             sxm.val[1] = vshrq_n_u16(sxm.val[1], 8);
868: 
869:             sxm.val[0] = vshlq_n_u16(sxm.val[0], 8);                // shift << 8, so we're prepared
870:             sxm.val[1] = vshlq_n_u16(sxm.val[1], 8);                // to have final format << 24
871: 
872:             sx01 = vzipq_u8(zero, (uint8x16_t)sxm.val[0]);          // interleave
873:             sx23 = vzipq_u8(zero, (uint8x16_t)sxm.val[1]);          // interleave
874:                                                                     // already shifted by 24
875: 
876:             r0  = vorrq_u32(d0, (uint32x4_t)sx01.val[0]);           // or
877:             r1  = vorrq_u32(d1, (uint32x4_t)sx01.val[1]);           // or
878:             r2  = vorrq_u32(d2, (uint32x4_t)sx23.val[0]);           // or
879:             r3  = vorrq_u32(d3, (uint32x4_t)sx23.val[1]);           // or
880: 
881:             vst1q_u32(dst, r0);                                     // store
882:             vst1q_u32(dst + 4, r1);                                 // store
883:             vst1q_u32(dst + 8, r2);                                 // store
884:             vst1q_u32(dst + 12, r3);                                // store
885: 
886:             dst += 16;
887:             src += 4;
888:         , width);
889:         /* *INDENT-ON* */
890:         src = (const Uint32 *)((const Uint8 *)src + srcskip);
891:         dst = (Uint32 *)((Uint8 *)dst + dstskip);
892:     }
893: }
894: #endif
