1014: // Underline and Strikethrough style. Draw a line at the given row.
1015: static void Draw_Line(TTF_Direction direction, const SDL_Surface *textbuf, int column, int row, int line_width, int line_thickness, Uint32 color, const render_mode_t render_mode)
1016: {
1017:     int tmp    = row + line_thickness - textbuf->h;
1018:     int x_offset = column * SDL_BYTESPERPIXEL(textbuf->format);
1019:     Uint8 *dst = (Uint8 *)textbuf->pixels + row * textbuf->pitch + x_offset;
1020: 
1021:     // No Underline/Strikethrough style if direction is vertical
1022:     if (direction == TTF_DIRECTION_TTB || direction == TTF_DIRECTION_BTT) {
1023:         return;
1024:     }
1025: 
1026:     /* Not needed because of "font->height = SDL_max(font->height, bottom_row);".
1027:      * But if you patch to render textshaping and break line in middle of a cluster,
1028:      * (which is a bad usage and a corner case), you need this to prevent out of bounds.
1029:      * You can get an "ystart" for the "whole line", which is different (and smaller)
1030:      * than the ones of the "splitted lines". */
1031:     if (tmp > 0) {
1032:         line_thickness -= tmp;
1033:     }
1034:     /* Previous case also happens with SDF (render_sdf) , because 'spread' property
1035:      * requires to increase 'ystart'
1036:      * Check for valid value anyway.  */
1037:     if (line_thickness <= 0) {
1038:         return;
1039:     }
1040: 
1041:     // Wrapped mode with an unbroken line: 'line_width' is greater that 'textbuf->w'
1042:     line_width = SDL_min(line_width, textbuf->w);
1043: 
1044:     if (render_mode == RENDER_BLENDED || render_mode == RENDER_LCD) {
1045:         while (line_thickness--) {
1046:             SDL_memset4(dst, color, line_width);
1047:             dst += textbuf->pitch;
1048:         }
1049:     } else {
1050:         while (line_thickness--) {
