1057: static void Draw_Line_TextEngine(TTF_Direction direction, int width, int height, int column, int row, int line_width, int line_thickness, TTF_DrawOperation *ops, int *current_op)
1058: {
1059:     int op_index = *current_op;
1060:     TTF_DrawOperation *op = &ops[op_index];
1061:     int tmp    = row + line_thickness - height;
1062: 
1063:     // No Underline/Strikethrough style if direction is vertical
1064:     if (direction == TTF_DIRECTION_TTB || direction == TTF_DIRECTION_BTT) {
1065:         return;
1066:     }
1067: 
1068:     /* Not needed because of "font->height = SDL_max(font->height, bottom_row);".
1069:      * But if you patch to render textshaping and break line in middle of a cluster,
1070:      * (which is a bad usage and a corner case), you need this to prevent out of bounds.
1071:      * You can get an "ystart" for the "whole line", which is different (and smaller)
1072:      * than the ones of the "splitted lines". */
1073:     if (tmp > 0) {
1074:         line_thickness -= tmp;
1075:     }
1076:     /* Previous case also happens with SDF (render_sdf) , because 'spread' property
1077:      * requires to increase 'ystart'
1078:      * Check for valid value anyway.  */
1079:     if (line_thickness <= 0) {
1080:         return;
1081:     }
1082: 
1083:     // Wrapped mode with an unbroken line: 'line_width' is greater that 'width'
1084:     line_width = SDL_min(line_width, width);
1085: 
1086:     op = &ops[op_index++];
1087:     op->cmd = TTF_DRAW_COMMAND_FILL;
1088:     op->fill.rect.x = column;
1089:     op->fill.rect.y = row;
1090:     op->fill.rect.w = line_width;
1091:     op->fill.rect.h = line_thickness;
1092:     *current_op = op_index;
1093: }
