1095: static void clip_glyph(int *_x, int *_y, TTF_Image *image, const SDL_Surface *textbuf, int is_lcd)
1096: {
1097:     int above_w;
1098:     int above_h;
1099:     int x = *_x;
1100:     int y = *_y;
1101: 
1102:     int srcbpp = 1;
1103:     if (image->is_color || is_lcd) {
1104:         srcbpp = 4;
1105:     }
1106: 
1107:     // Don't go below x=0
1108:     if (x < 0) {
1109:         int tmp = -x;
1110:         x = 0;
1111:         image->width  -= tmp;
1112:         image->buffer += srcbpp * tmp;
1113:     }
1114:     // Don't go above textbuf->w
1115:     above_w = x + image->width - textbuf->w;
1116:     if (above_w > 0) {
1117:         image->width -= above_w;
1118:     }
1119:     // Don't go below y=0
1120:     if (y < 0) {
1121:         int tmp = -y;
1122:         y = 0;
1123:         image->rows   -= tmp;
1124:         image->buffer += tmp * image->pitch;
1125:     }
1126:     // Don't go above textbuf->h
1127:     above_h = y + image->rows - textbuf->h;
1128:     if (above_h > 0) {
1129:         image->rows -= above_h;
1130:     }
1131:     // Could be negative if (x > textbuf->w), or if (x + width < 0)
1132:     image->width = SDL_max(0, image->width);
1133:     image->rows  = SDL_max(0, image->rows);
1134: 
1135:     /* After 'image->width' clipping:
1136:      * Make sure 'rows' is also 0, so it doesn't break USE_DUFFS_LOOP */
1137:     if (image->width == 0) {
1138:         image->rows = 0;
1139:     }
1140: 
1141:     *_x = x;
1142:     *_y = y;
1143: }
