1432: static bool Render_Line_TextEngine(TTF_Font *font, TTF_Direction direction, int xstart, int ystart, int width, int height, TTF_DrawOperation *ops, int *current_op, TTF_SubString *clusters, int *current_cluster, int cluster_offset, int line_index)
1433: {
1434:     int i;
1435:     int op_index = *current_op;
1436:     int cluster_index = *current_cluster;
1437:     int last_offset = -1;
1438:     TTF_SubString *cluster = NULL;
1439: 
1440:     SDL_Rect bounds;
1441:     bounds.x = xstart;
1442:     bounds.y = ystart;
1443:     bounds.w = 0;
1444:     bounds.h = font->height;
1445: 
1446:     for (i = 0; i < font->positions->len; i++) {
1447:         GlyphPosition *pos = &font->positions->pos[i];
1448:         TTF_Font *glyph_font = pos->font;
1449:         FT_UInt idx = pos->index;
1450:         int x = pos->x;
1451:         int y = pos->y;
1452:         int offset = pos->offset;
1453:         c_glyph *glyph = pos->glyph;
1454:         int above_w, above_h;
1455:         int glyph_x = 0;
1456:         int glyph_y = 0;
1457:         int glyph_width = glyph->sz_width;
1458:         int glyph_rows = glyph->sz_rows;
1459:         TTF_DrawOperation *op;
1460: 
1461:         // Position updated after glyph rendering
1462:         x = xstart + FT_FLOOR(x) + glyph->sz_left;
1463:         y = ystart + FT_FLOOR(y) - glyph->sz_top;
1464: 
1465:         if (!glyph_font->render_sdf) {
1466:             // Make sure glyph is inside text area
1467:             above_w = x + glyph_width - (xstart + width);
1468:             above_h = y + glyph_rows  - (ystart + height);
1469: 
1470:             if (x < 0) {
1471:                 int tmp = -x;
1472:                 x = 0;
1473:                 glyph_x += tmp;
1474:                 glyph_width -= tmp;
1475:             }
1476:             if (above_w > 0) {
1477:                 glyph_width -= above_w;
1478:             }
1479:             if (y < 0) {
1480:                 int tmp = -y;
1481:                 y = 0;
1482:                 glyph_y += tmp;
1483:                 glyph_rows -= tmp;
1484:             }
1485:             if (above_h > 0) {
1486:                 glyph_rows -= above_h;
1487:             }
1488:         }
1489: 
1490:         if (glyph_width > 0 && glyph_rows > 0) {
1491:             op = &ops[op_index++];
1492:             op->cmd = TTF_DRAW_COMMAND_COPY;
1493:             op->copy.text_offset = offset;
1494:             op->copy.glyph_font = glyph_font;
1495:             op->copy.glyph_index = idx;
1496:             op->copy.src.x = glyph_x;
1497:             op->copy.src.y = glyph_y;
1498:             op->copy.src.w = glyph_width + 2 * font->outline;
1499:             op->copy.src.h = glyph_rows + 2 * font->outline;
1500:             op->copy.dst.x = x;
1501:             op->copy.dst.y = y;
1502:             op->copy.dst.w = op->copy.src.w;
1503:             op->copy.dst.h = op->copy.src.h;
1504:             if (glyph_font->render_sdf) {
1505:                 op->copy.dst.x -= DEFAULT_SDF_SPREAD;
1506:                 op->copy.dst.y -= DEFAULT_SDF_SPREAD;
1507:             }
1508:         } else {
1509:             // Use the distance to the next glyph as our bounds width
1510:             glyph_width = FT_FLOOR(pos->x_advance) + 2 * font->outline;
1511:         }
1512: 
1513:         bounds.x = x;
1514:         bounds.w = glyph_width;
1515:         if (offset != last_offset) {
1516:             cluster = &clusters[cluster_index++];
1517:             cluster->offset = cluster_offset + offset;
1518:             cluster->line_index = line_index;
1519:             if (direction == TTF_DIRECTION_INVALID) {
1520:                 if (last_offset == -1) {
1521:                     if (i < (font->positions->len - 1)) {
1522:                         GlyphPosition *next = &font->positions->pos[i + 1];
1523:                         if (offset < next->offset) {
1524:                             cluster->flags = TTF_DIRECTION_LTR;
1525:                         } else {
1526:                             cluster->flags = TTF_DIRECTION_RTL;
1527:                         }
1528:                     } else {
1529:                         cluster->flags = TTF_DIRECTION_INVALID;
1530:                     }
1531:                 } else {
1532:                     if (offset > last_offset) {
1533:                         cluster->flags = TTF_DIRECTION_LTR;
1534:                     } else {
1535:                         cluster->flags = TTF_DIRECTION_RTL;
1536:                     }
1537:                 }
1538:             } else {
1539:                 cluster->flags = direction;
1540:             }
1541:             SDL_copyp(&cluster->rect, &bounds);
1542: 
1543:             last_offset = offset;
1544:         } else if (cluster) {
1545:             SDL_GetRectUnion(&cluster->rect, &bounds, &cluster->rect);
1546:         }
1547:     }
1548: 
1549:     *current_op = op_index;
1550:     *current_cluster = cluster_index;
1551:     return true;
1552: }
