1554: /* Create a surface with memory:
1555:  * - pitch is rounded to alignment
1556:  * - address is aligned
1557:  *
1558:  * If format is 4 bytes per pixel, bgcolor is used to initialize each
1559:  * 4-byte word in the image data.
1560:  *
1561:  * Otherwise, the low byte of format is used to initialize each byte
1562:  * in the image data.
1563:  */
1564: static SDL_Surface *AllocateAlignedPixels(size_t width, size_t height, SDL_PixelFormat format, Uint32 bgcolor)
1565: {
1566:     const size_t alignment = Get_Alignment() - 1;
1567:     const size_t bytes_per_pixel = SDL_BYTESPERPIXEL(format);
1568:     SDL_Surface *textbuf = NULL;
1569:     size_t size;
1570:     void *pixels;
1571:     size_t pitch;
1572: 
1573:     /*
1574:      * 1/ Line size is "width * bytes_per_pixel"
1575:      *
1576:      * 2/ We add a right padding, because we process glyph from source to destination by
1577:      * blocks of 'alignment + 1' bytes.  (Using SSE 128 instruction for instance when renderering,
1578:      * but this isn't always the case for all modes).
1579:      *
1580:      * We need to make sure the last transfer doesn't go too much outside!
1581:      *
1582:      * Considerer also for instance, that when we read 1 block of 16 bytes from source, for the blended
1583:      * format (bbp == 4), it writes(and reads) 4 blocks of 16 in the dest, like BG_Blended_SSE()).
1584:      *
1585:      * Remark: for Solid/Shaded, block ratio read/write is 1:1.
1586:      * For Color / LCD / SDF, it is byte vs byte or int. They are also fallback for
1587:      * Solid/Shaded/Blend, when it isn't contained in textbuf, see clip_glyph()
1588:      *
1589:      * So the pitch must contain "width * bytes_per_pixel", plus in the
1590:      * worst case, writing at last pixel (1 * bytes_per_pixel), an extra "alignment * bytes_per_pixel".
1591:      * (Using the destination bytes_per_pixel is a safe upper bound for the ratio).
1592:      *
1593:      * Also, we always write at a block-aligned adresses.
1594:      * - address is aligned 'SDL_aligned_alloc((alignment + 1), size)'
1595:      * - the pitch is aligned 'pitch &= ~alignment'
1596:      * So that each line is aligned.
1597:      *
1598:      * Remark: we can safely align the pitch (pitch &= ~alignment), without adding more to pitch,
1599:      * becaJuse we know we always write blocks at block-aligned addresses.
1600:      * So pitch won't need to be more than a multiple of block size.
1601:      *
1602:      * So pitch is:
1603:      *  ((width * bytes_per_pixel) + (alignment * bytes_per_pixel) ) & ~alignment
1604:      *  ==
1605:      *  ((width + alignment) * bytes_per_pixel ) & ~alignment
1606:      *
1607:      * which is different from:
1608:      *  ((width + alignment) & ~alignment)) * bytes_per_pixel  (which fails.)
1609:      *
1610:      * Remark: to test memory issues, it is useful to patch SDL to use real memalign/free
1611:      * so that valgrind check more precisely out of bounds.
1612:      */
1613:     if (width > SDL_MAX_SINT32 ||
1614:         height > SDL_MAX_SINT32 ||
1615:         !SDL_size_add_check_overflow(width, alignment, &pitch) ||
1616:         !SDL_size_mul_check_overflow(pitch, bytes_per_pixel, &pitch) ||
1617:         pitch > SDL_MAX_SINT32) {
1618:         return NULL;
1619:     }
1620:     pitch &= ~alignment;
1621: 
1622:     if (!SDL_size_mul_check_overflow(height, pitch, &size)) {
1623:         // Overflow...
1624:         return NULL;
1625:     }
1626: 
1627:     pixels = SDL_aligned_alloc(alignment + 1, size);
1628:     if (pixels == NULL) {
1629:         return NULL;
1630:     }
1631: 
1632:     textbuf = SDL_CreateSurfaceFrom((int)width, (int)height, format, pixels, (int)pitch);
1633:     if (textbuf == NULL) {
1634:         SDL_aligned_free(pixels);
1635:         return NULL;
1636:     }
1637: 
1638:     // Let SDL handle the memory allocation
1639:     textbuf->flags &= ~SDL_SURFACE_PREALLOCATED;
1640:     textbuf->flags |= SDL_SURFACE_SIMD_ALIGNED;
1641: 
1642:     // Allocate a palette if needed
1643:     if (SDL_ISPIXELFORMAT_INDEXED(format)) {
1644:         if (!SDL_CreateSurfacePalette(textbuf)) {
1645:             SDL_DestroySurface(textbuf);
1646:             return NULL;
1647:         }
1648:     }
1649: 
1650:     if (bytes_per_pixel == 4) {
1651:         SDL_memset4(pixels, bgcolor, size / 4);
1652:     }
1653:     else {
1654:         SDL_memset(pixels, (bgcolor & 0xff), size);
1655:     }
1656: 
1657:     return textbuf;
1658: }
