1660: static SDL_Surface* Create_Surface_Solid(int width, int height, SDL_Color fg, Uint32 *color)
1661: {
1662:     SDL_Surface *textbuf = AllocateAlignedPixels(width, height, SDL_PIXELFORMAT_INDEX8, 0);
1663:     if (textbuf == NULL) {
1664:         return NULL;
1665:     }
1666: 
1667:     // Underline/Strikethrough color style
1668:     *color = 1;
1669: 
1670:     // Fill the palette: 1 is foreground
1671:     {
1672:         SDL_Palette *palette = SDL_GetSurfacePalette(textbuf);
1673:         palette->colors[0].r = 255 - fg.r;
1674:         palette->colors[0].g = 255 - fg.g;
1675:         palette->colors[0].b = 255 - fg.b;
1676:         palette->colors[1].r = fg.r;
1677:         palette->colors[1].g = fg.g;
1678:         palette->colors[1].b = fg.b;
1679:         palette->colors[1].a = fg.a;
1680:     }
1681: 
1682:     SDL_SetSurfaceColorKey(textbuf, true, 0);
1683: 
1684:     return textbuf;
1685: }
