1687: static SDL_Surface* Create_Surface_Shaded(int width, int height, SDL_Color fg, SDL_Color bg, Uint32 *color)
1688: {
1689:     SDL_Surface *textbuf = AllocateAlignedPixels(width, height, SDL_PIXELFORMAT_INDEX8, 0);
1690:     Uint8 bg_alpha = bg.a;
1691:     if (textbuf == NULL) {
1692:         return NULL;
1693:     }
1694: 
1695:     // Underline/Strikethrough color style
1696:     *color = NUM_GRAYS - 1;
1697: 
1698:     // Support alpha blending
1699:     if (fg.a != SDL_ALPHA_OPAQUE || bg.a != SDL_ALPHA_OPAQUE) {
1700:         SDL_SetSurfaceBlendMode(textbuf, SDL_BLENDMODE_BLEND);
1701: 
1702:         // Would disturb alpha palette
1703:         if (bg.a == SDL_ALPHA_OPAQUE) {
1704:             bg.a = 0;
1705:         }
1706:     }
1707: 
1708:     // Fill the palette with NUM_GRAYS levels of shading from bg to fg
1709:     {
1710:         SDL_Palette *palette = SDL_GetSurfacePalette(textbuf);
1711:         int rdiff  = fg.r - bg.r;
1712:         int gdiff  = fg.g - bg.g;
1713:         int bdiff  = fg.b - bg.b;
1714:         int adiff  = fg.a - bg.a;
1715:         int sign_r = (rdiff >= 0) ? 1 : 255;
1716:         int sign_g = (gdiff >= 0) ? 1 : 255;
1717:         int sign_b = (bdiff >= 0) ? 1 : 255;
1718:         int sign_a = (adiff >= 0) ? 1 : 255;
1719:         int i;
1720: 
1721:         for (i = 0; i < NUM_GRAYS; ++i) {
1722:             /* Compute color[i] = (i * color_diff / 255) */
1723:             int tmp_r = i * rdiff;
1724:             int tmp_g = i * gdiff;
1725:             int tmp_b = i * bdiff;
1726:             int tmp_a = i * adiff;
1727:             palette->colors[i].r = (Uint8)(bg.r + DIVIDE_BY_255_SIGNED(tmp_r, sign_r));
1728:             palette->colors[i].g = (Uint8)(bg.g + DIVIDE_BY_255_SIGNED(tmp_g, sign_g));
1729:             palette->colors[i].b = (Uint8)(bg.b + DIVIDE_BY_255_SIGNED(tmp_b, sign_b));
1730:             palette->colors[i].a = (Uint8)(bg.a + DIVIDE_BY_255_SIGNED(tmp_a, sign_a));
1731:         }
1732: 
1733:         // Make sure background has the correct alpha value
1734:         palette->colors[0].a = bg_alpha;
1735:     }
1736: 
1737:     return textbuf;
1738: }
1739: 
1740: static SDL_Surface *Create_Surface_Blended(int width, int height, SDL_Color fg, Uint32 *color)
1741: {
1742:     SDL_Surface *textbuf = NULL;
1743:     Uint32 bgcolor;
1744: 
1745:     // Background color: initialize with fg and 0 alpha
1746:     bgcolor = (fg.r << 16) | (fg.g << 8) | fg.b;
1747: 
1748:     // Underline/Strikethrough color style
1749:     *color = bgcolor | ((Uint32)fg.a << 24);
1750: 
1751:     // Create the target surface if required
1752:     if (width != 0) {
1753:         textbuf = AllocateAlignedPixels(width, height, SDL_PIXELFORMAT_ARGB8888, bgcolor);
1754:         if (textbuf == NULL) {
1755:             return NULL;
1756:         }
1757:     }
1758: 
1759:     return textbuf;
1760: }
1761: 
1762: static SDL_Surface* Create_Surface_LCD(int width, int height, SDL_Color fg, SDL_Color bg, Uint32 *color)
1763: {
1764:     SDL_Surface *textbuf = NULL;
1765:     Uint32 bgcolor;
1766: 
1767:     // Background color
1768:     bgcolor = (((Uint32)bg.a) << 24) | (bg.r << 16) | (bg.g << 8) | bg.b;
1769: 
1770:     // Underline/Strikethrough color style
1771:     *color = (((Uint32)bg.a) << 24) | (fg.r << 16) | (fg.g << 8) | fg.b;
1772: 
1773:     // Create the target surface if required
1774:     if (width != 0) {
1775:         textbuf = AllocateAlignedPixels(width, height, SDL_PIXELFORMAT_ARGB8888, bgcolor);
1776:         if (textbuf == NULL) {
1777:             return NULL;
1778:         }
1779:     }
1780: 
1781:     return textbuf;
1782: }
