2294: bool TTF_AddFallbackFont(TTF_Font *font, TTF_Font *fallback)
2295: {
2296:     TTF_CHECK_FONT(font, false);
2297:     TTF_CHECK_POINTER("fallback", fallback, false);
2298: 
2299:     TTF_FontList *fallback_entry = (TTF_FontList *)SDL_calloc(1, sizeof(*fallback_entry));
2300:     TTF_FontList *fallback_for_entry = (TTF_FontList *)SDL_calloc(1, sizeof(*fallback_entry));
2301:     if (!fallback_entry || !fallback_for_entry) {
2302:         SDL_free(fallback_entry);
2303:         SDL_free(fallback_for_entry);
2304:         return false;
2305:     }
2306: 
2307:     TTF_FontList *prev = NULL;
2308:     for (TTF_FontList *list = font->fallbacks; list; prev = list, list = list->next) {
2309:         continue;
2310:     }
2311:     fallback_entry->font = fallback;
2312:     if (prev) {
2313:         prev->next = fallback_entry;
2314:     } else {
2315:         font->fallbacks = fallback_entry;
2316:     }
2317: 
2318:     prev = NULL;
2319:     for (TTF_FontList *list = fallback->fallback_for; list; prev = list, list = list->next) {
2320:         continue;
2321:     }
2322:     fallback_for_entry->font = font;
2323:     if (prev) {
2324:         prev->next = fallback_for_entry;
2325:     } else {
2326:         fallback->fallback_for = fallback_for_entry;
2327:     }
2328: 
2329:     UpdateFontText(font, NULL);
2330:     return true;
2331: }
