2382: // Update font parameter depending on a style change
2383: static void TTF_InitFontMetrics(TTF_Font *font)
2384: {
2385:     FT_Face face = font->face;
2386:     int underline_offset;
2387: 
2388:     // Make sure that our font face is scalable (global metrics)
2389:     if (FT_IS_SCALABLE(face)) {
2390:         // Get the scalable font metrics for this font
2391:         FT_Fixed scale       = face->size->metrics.y_scale;
2392:         font->ascent         = FT_CEIL(FT_MulFix(face->ascender, scale));
2393:         font->descent        = FT_CEIL(FT_MulFix(face->descender, scale));
2394:         font->height         = FT_CEIL(FT_MulFix(face->ascender - face->descender, scale));
2395:         font->lineskip       = FT_CEIL(FT_MulFix(face->height, scale));
2396:         underline_offset     = FT_FLOOR(FT_MulFix(face->underline_position, scale));
2397:         font->line_thickness = FT_FLOOR(FT_MulFix(face->underline_thickness, scale));
2398:     } else {
2399:         // Get the font metrics for this font, for the selected size
2400:         font->ascent         = FT_CEIL(face->size->metrics.ascender);
2401:         font->descent        = FT_CEIL(face->size->metrics.descender);
2402:         font->height         = FT_CEIL(face->size->metrics.height);
2403:         font->lineskip       = FT_CEIL(face->size->metrics.height);
2404:         /* face->underline_position and face->underline_height are only
2405:          * relevant for scalable formats (see freetype.h FT_FaceRec) */
2406:         underline_offset     = font->descent / 2;
2407:         font->line_thickness = 1;
2408:     }
2409: 
2410:     if (font->line_thickness < 1) {
2411:         font->line_thickness = 1;
2412:     }
2413: 
2414:     font->underline_top_row     = font->ascent - underline_offset - 1;
2415:     font->strikethrough_top_row = font->height / 2;
2416: 
2417:     // Adjust OutlineStyle, only for scalable fonts
2418:     /* TTF_Size(): increase w and h by 2 * outline, translate positionning by 1 * outline */
2419:     if (font->outline > 0) {
2420:         int fo = font->outline;
2421:         font->line_thickness        += 2 * fo;
2422:         font->underline_top_row     -= fo;
2423:         font->strikethrough_top_row -= fo;
2424:     }
2425: 
2426:     // Robustness: no negative values allowed
2427:     font->underline_top_row     = SDL_max(0, font->underline_top_row);
2428:     font->strikethrough_top_row = SDL_max(0, font->strikethrough_top_row);
2429: 
2430:     // Update height according to the needs of the underline style
2431:     if (TTF_HANDLE_STYLE_UNDERLINE(font)) {
2432:         int bottom_row = font->underline_top_row + font->line_thickness;
2433:         font->height = SDL_max(font->height, bottom_row);
2434:     }
2435:     // Update height according to the needs of the strikethrough style
2436:     if (TTF_HANDLE_STYLE_STRIKETHROUGH(font)) {
2437:         int bottom_row = font->strikethrough_top_row + font->line_thickness;
2438:         font->height = SDL_max(font->height, bottom_row);
2439:     }
2440: 
2441: #if defined(DEBUG_FONTS)
2442:     SDL_Log("Font metrics:");
2443:     SDL_Log("ascent = %d, descent = %d", font->ascent, font->descent);
2444:     SDL_Log("height = %d, lineskip = %d", font->height, font->lineskip);
2445:     SDL_Log("underline_offset = %d, line_thickness = %d", underline_offset, font->line_thickness);
2446:     SDL_Log("underline_top_row = %d, strikethrough_top_row = %d", font->underline_top_row, font->strikethrough_top_row);
2447:     SDL_Log("scalable=%d fixed_sizes=%d", FT_IS_SCALABLE(face), FT_HAS_FIXED_SIZES(face));
2448: #endif
2449: 
2450:     font->glyph_overhang = face->size->metrics.y_ppem / 10;
2451: }
